	 *                     subdir: non-empty-string,
	 *                     basedir: non-empty-string,
	 *                     baseurl: non-empty-string,
	 *                 }
	 *                |array{ error: non-empty-string }
	 */
	public function wp_upload_dir( $time = null, $create_dir = true, $refresh_cache = false );

	/**
	 * Retrieves uploads directory information.
	 *
	 * Same as wp_upload_dir() but "light weight" as it doesn't attempt to create the uploads directory.
	 * Intended for use in themes, when only 'basedir' and 'baseurl' are needed, generally in all cases
	 * when not uploading files.
	 *
	 * @since 4.5.0
	 *
	 * @see wp_upload_dir()
	 *
	 * @return array See wp_upload_dir() for description.
	 * @phpstan-return array{
	 *                     path: non-empty-string,
	 *                     url: non-empty-string,
	 *                     subdir: non-empty-string,
	 *                     basedir: non-empty-string,
	 *                     baseurl: non-empty-string,
	 *                 }
	 *                |array{ error: non-empty-string }
	 */
	public function wp_get_upload_dir();

	/**
	 * Creates a file in the upload folder with given content.
	 *
	 * If there is an error, then the key 'error' will exist with the error message.
	 * If success, then the key 'file' will have the unique file path, the 'url' key
	 * will have the link to the new file. and the 'error' key will be set to false.
	 *
	 * This function will not move an uploaded file to the upload folder. It will
	 * create a new file with the content in $bits parameter. If you move the upload
	 * file, read the content of the uploaded file, and then you can give the
	 * filename and content to this function, which will add it to the upload
	 * folder.
	 *
	 * The permissions will be set on the new file automatically by this function.
	 *
	 * @since 2.0.0
	 *
	 * @param string      $name       Filename.
	 * @param null|string $deprecated Not used. Set to null.
	 * @param string      $bits       File content
	 * @param string|null $time       Optional. Time formatted in 'yyyy/mm'. Default null.
	 * @return array {
	 *     Information about the newly-uploaded file.
	 *
	 *     @type string       $file  Filename of the newly-uploaded file.
	 *     @type string       $url   URL of the uploaded file.
	 *     @type string       $type  File type.
	 *     @type string|false $error Error message, if there has been an error.
	 * }
	 */
	public function wp_upload_bits( $name, $deprecated, $bits, $time = null );
}
